-- Word meaning review 2026-10-03: judged gloss/note fixes for lemmas, forms and per-sentence token glosses.
-- Each update is guarded on the value it replaces, so a row edited since the snapshot is left alone.
update public.lemmas set gloss_note_en = 'Sweet bakery pastries (medialunas, vigilantes, bolas de fraile), bought by the dozen. Also means invoice.' where id = 'bcc4b59e-a59c-5544-8f3e-3abb177c3110' and gloss_note_en is not distinct from null; -- factura
update public.lemmas set gloss_en = 'mate, herbal tea', gloss_note_en = 'Bitter yerba tea sipped through a metal straw (bombilla) from a gourd, shared around a circle.' where id = 'f256a972-25f8-53b9-94fc-83251ad9eb44' and gloss_en is not distinct from 'mate' and gloss_note_en is not distinct from 'the drink'; -- mate
update public.lemmas set gloss_note_en = 'Small sweet croissant: de manteca (butter, glazed) or de grasa (plainer). Breakfast staple.' where id = 'aa5883af-95bf-5b63-a33a-9dc346c549ca' and gloss_note_en is not distinct from 'a small sweet pastry, the Argentine breakfast staple'; -- medialuna
update public.lemmas set gloss_note_en = 'Argentines often start an answer with ''Y...'' meaning ''well...'': Y, depende.' where id = '0767536f-f3cc-5cb2-a985-f8f07d162177' and gloss_note_en is not distinct from null; -- y
update public.lemmas set gloss_en = 'food, meal' where id = 'bc25e978-42d0-5c18-8a5d-fc17086dfaaa' and gloss_en is not distinct from 'the food, a meal'; -- comida
update public.lemmas set gloss_note_en = 'Argentines usually say buen día (singular), not buenos días.' where id = 'b13a07a4-9ee8-5527-a1fd-573116f082e0' and gloss_note_en is not distinct from null; -- buen día
update public.lemmas set gloss_en = 'great, perfect', gloss_note_en = 'Literally ''jewel''. Very common casual way to say great or perfect.' where id = '177880cc-eec3-5ffc-8d44-4af5394aaff9' and gloss_en is not distinct from 'perfect, all set' and gloss_note_en is not distinct from '¡Joya! — great, sorted'; -- joya
update public.lemmas set gloss_en = 'you', gloss_note_en = 'Argentina''s ''you'' for everyone, instead of tú, with its own verb forms: vos sos, vos tenés.' where id = '9b1d24a2-df9c-5636-b5b5-bb96eae77ffb' and gloss_en is not distinct from 'you (informal)' and gloss_note_en is not distinct from null; -- vos
update public.forms set gloss_en = 'rounds of mate', gloss_note_en = null where id = '81873ef2-a7c4-55c3-942b-a3733183012a' and gloss_en is not distinct from 'mates' and gloss_note_en is not distinct from 'rounds of mate'; -- mates
update public.forms set gloss_en = 'will be, is probably' where id = '905cfd2f-3a62-5fc0-b2c9-fc2df8ca0bdd' and gloss_en is not distinct from 'will be, can be'; -- será
update public.forms set gloss_en = 'you would be' where id = 'a61e38e3-a3c6-589c-a580-19de2879e4ee' and gloss_en is not distinct from 'you would be (someone, something)'; -- serías
update public.lemmas set gloss_note_en = 'Argentines also use it to mean ''anyway, still'': "Igualmente voy" = I''m going anyway.' where id = 'dfbb1101-826f-57e1-8753-ef9b74894a04' and gloss_note_en is not distinct from null; -- igualmente
update public.lemmas set gloss_note_en = 'In Buenos Aires, ''provincia'' alone often means Buenos Aires Province, outside the city: vivo en provincia.' where id = '626ce0ad-87ad-5cea-bfde-9b62c8f5e6b8' and gloss_note_en is not distinct from null; -- provincia
update public.lemmas set gloss_note_en = 'Zona norte/sur/oeste: the suburbs around Buenos Aires city in that direction.' where id = 'c2f22cd2-5951-5efe-9942-81bda22904e7' and gloss_note_en is not distinct from null; -- zona
update public.lemmas set gloss_note_en = 'From the city of Buenos Aires (the port city), not the province.' where id = '5ef202bd-870a-53f6-8374-cd809156a220' and gloss_note_en is not distinct from null; -- porteño
update public.lemmas set gloss_en = 'Spanish, from Spain', gloss_note_en = 'Argentines call the language ''castellano'', and casually call any Spaniard ''gallego''.' where id = '15d97f58-b232-5422-86cc-b7681a22eea6' and gloss_en is not distinct from 'from Spain' and gloss_note_en is not distinct from null; -- español
update public.lemmas set gloss_note_en = 'Also used for a fiancé and for the groom at a wedding.' where id = '748e647b-17ec-5b6b-9a16-bbe88693ab18' and gloss_note_en is not distinct from null; -- novio
update public.forms set gloss_en = '(that) I know, (that) he/she knows' where id = 'b3066a8f-758a-548c-8d32-4483c786931a' and gloss_en is not distinct from 'know (so that I, so that he/she know)'; -- sepa
update public.forms set gloss_en = 'boyfriend and girlfriend, a couple; bride and groom' where id = '683521b7-6baf-5b69-a0cc-e3473c23c50c' and gloss_en is not distinct from 'boyfriend and girlfriend, a couple'; -- novios
update public.lemmas set gloss_en = 'dad, old man', gloss_note_en = 'Mi viejo / mi vieja = my dad / my mom; mis viejos = my parents. Warm, not rude.' where id = '78f277d0-1761-5697-b08a-ac7c0ef24fd0' and gloss_en is not distinct from 'old man' and gloss_note_en is not distinct from null; -- viejo
update public.lemmas set gloss_note_en = 'Two soft cookies with dulce de leche in between, often covered in chocolate. Sold at every kiosco.' where id = '0720a54d-438a-5537-be26-3f524507e46d' and gloss_note_en is not distinct from 'two soft biscuits sandwiched with dulce de leche'; -- alfajor
update public.lemmas set gloss_en = 'package, pack' where id = 'a44ca707-5cf5-56e4-a7de-aef226c7dafb' and gloss_en is not distinct from 'packet, pack'; -- paquete
update public.lemmas set gloss_note_en = 'Usually ham and cheese on thin crustless bread (pan de miga), toasted. A café classic.' where id = 'a38c336d-e76a-5b36-a253-cc6cbd11abd0' and gloss_note_en is not distinct from null; -- tostado
update public.lemmas set gloss_en = 'his, her, their, your (plural)' where id = '0cf963a2-ecea-5914-9310-d8b5740a34ae' and gloss_en is not distinct from 'his, her, their'; -- su
