update public.forms set gloss_en = 'we would have' where id = 'f7037f0a-9270-5543-be5a-981abadac9c9' and gloss_en is not distinct from 'we would have (got)'; -- tendríamos
update public.forms set gloss_en = 'you would have; you should (tendrías que)' where id = '40fda59f-22ff-52a0-bab0-d9471212a946' and gloss_en is not distinct from 'you''d have (to), you ought to'; -- tendrías
update public.forms set gloss_en = 'packages, packs' where id = 'e86cd459-3cc1-5f5e-a73f-7a74bda5b556' and gloss_en is not distinct from 'packets'; -- paquetes
update public.lemmas set gloss_note_en = 'Also used to call someone: ''¿Qué hacés, flaco?'' = hey, man (even if he isn''t thin).' where id = 'bd815776-0cf8-54bb-a403-d7dd33237fae' and gloss_note_en is not distinct from null; -- flaco
update public.lemmas set gloss_note_en = 'Argentines say mellizos for twins in general; gemelos is used mostly for identical twins.' where id = '84fe4acf-86c0-54a1-94d6-550307aeb0ba' and gloss_note_en is not distinct from 'Argentines say mellizos for any twins'; -- mellizo
update public.lemmas set gloss_note_en = 'False friend: means friendly or likeable, not ''sympathetic''.' where id = 'ba8f9e9b-bcdf-5085-bc18-7c5a808f343b' and gloss_note_en is not distinct from null; -- simpático
update public.lemmas set gloss_note_en = 'Argentines give directions and distances in cuadras (about 100 m each).' where id = 'eb1a8761-4c5a-5e4a-b7f0-0330c3541c9b' and gloss_note_en is not distinct from null; -- cuadra
update public.forms set gloss_en = 'they are, you guys are (subjunctive)' where id = '64754e47-f2ae-5e62-9070-4834634ce303' and gloss_en is not distinct from 'are (that they be there, that they be so)'; -- estén
update public.lemmas set gloss_en = 'to have (+ past participle); there to be (hay)' where id = 'c2a40273-851a-5287-a16f-72c488149cba' and gloss_en is not distinct from 'there to be'; -- haber
update public.lemmas set gloss_note_en = 'An Argentine bar is often a café: coffee, medialunas and food all day, not just drinks.' where id = '13408ae2-eea4-526e-838e-e3ae7aec7ed8' and gloss_note_en is not distinct from null; -- bar
update public.lemmas set gloss_note_en = 'Short for subterráneo. Only Buenos Aires has a subte; lines are letters (A, B, C...).' where id = '84f91f6a-d1d9-5b7e-a12a-3ea747bbc703' and gloss_note_en is not distinct from null; -- subte
update public.lemmas set gloss_note_en = 'Subte lines are letters (la línea B); buses are numbers (la línea 60, or just ''el 60'').' where id = '0bf6e2dd-46d2-5b26-aa6e-4a116d2866d2' and gloss_note_en is not distinct from 'la línea B, la línea 60'; -- línea
update public.lemmas set gloss_en = 'park, square', gloss_note_en = 'A plaza is usually a green block with trees, benches and a playground, more like a small park.' where id = '50abe4c7-c28d-581c-b150-e89e71beaaac' and gloss_en is not distinct from 'square, park' and gloss_note_en is not distinct from null; -- plaza
update public.lemmas set gloss_note_en = 'Estar aburrido = to be bored; ser aburrido = to be boring.' where id = 'f3caa7e8-2434-510e-8dce-045bbfd71f93' and gloss_note_en is not distinct from null; -- aburrido
update public.lemmas set gloss_en = 'happy, glad' where id = '3aae4fdf-0cdb-5b63-affe-128ca6ab7d2d' and gloss_en is not distinct from 'glad, pleased'; -- contento
update public.lemmas set gloss_note_en = 'Short for tranquilo. Alone, ''tranqui'' means ''relax, don''t worry''.' where id = 'e712568e-0b65-5aa1-a556-f1d889e32cd6' and gloss_note_en is not distinct from null; -- tranqui
update public.lemmas set gloss_note_en = 'Said of a person: sexually aroused, or very angry. For ''I''m hot'' say ''tengo calor''.' where id = 'f30b1a76-0f36-5f04-b966-e962611c175c' and gloss_note_en is not distinct from 'said of a person: angry, or aroused'; -- caliente
update public.lemmas set gloss_en = 'ready; done, OK', gloss_note_en = 'Alone, ''¡Listo!'' means ''OK, done, that''s it'' and is used all the time.' where id = '089c19f6-c1ab-5ddd-b919-8e63f91b7c56' and gloss_en is not distinct from 'ready' and gloss_note_en is not distinct from null; -- listo
update public.lemmas set gloss_note_en = 'Argentines usually call Spanish ''castellano''; ''español'' is also understood and used.' where id = '3a9ef937-a899-5c1a-8e7e-c0a7f31ae67b' and gloss_note_en is not distinct from 'Argentines say castellano, not español'; -- castellano
update public.forms set gloss_en = 'there is, there are (subjunctive)' where id = '1c27ab37-ca92-57e2-8233-a445019d3c84' and gloss_en is not distinct from 'there is (that there be)'; -- haya
update public.forms set gloss_en = 'does, makes (he/she); it''s (weather); ago' where id = '229a2ee1-b1c9-5416-b88f-ffc0d8b5331a' and gloss_en is not distinct from 'does (he/she does)'; -- hace
update public.lemmas set gloss_note_en = 'Everyday Argentine word for work, more common than trabajar in casual talk. Laburo = job, work.' where id = '4828f42f-f984-5603-9cb1-36d5c1c4c737' and gloss_note_en is not distinct from null; -- laburar
update public.lemmas set gloss_en = 'little, not much' where id = 'efeec9de-3965-50ad-b865-4e55121bc1cd' and gloss_en is not distinct from 'a little'; -- poco
update public.lemmas set gloss_en = 'to drink, to take, to have', gloss_note_en = 'Used to take a bus, train or pill. Never use coger for ''take'': it is vulgar here.' where id = '4471441b-1d77-5fcb-9156-a5ba329d7478' and gloss_en is not distinct from 'to drink, to have' and gloss_note_en is not distinct from null; -- tomar
update public.lemmas set gloss_note_en = 'Mate amargo = mate without sugar. Calling a person amargo/amarga means a killjoy, a grump.' where id = '727aeb29-64fe-5b54-96a5-1c79413f61b7' and gloss_note_en is not distinct from null; -- amargo
update public.lemmas set gloss_note_en = 'Argentine staple, beef or chicken, often called ''mila''. A la napolitana = topped with ham, sauce and cheese.' where id = 'e61e0a86-d95b-5577-9474-297d8e12b8bc' and gloss_note_en is not distinct from null; -- milanesa
update public.forms set gloss_en = 'I work; (noun) work, job' where id = '1a16f931-a217-5a7e-9949-c501f2a399b4' and gloss_en is not distinct from 'I work'; -- laburo
update public.forms set gloss_en = 'you take, you drink (that you take)' where id = '92b4fa7d-d73a-5b6f-b413-113c1623ed0d' and gloss_en is not distinct from 'you catch, you drink (that you take)'; -- tomes
update public.forms set gloss_en = 'I drink, I take' where id = '64609644-11e7-5af2-8b9d-dcda0500090e' and gloss_en is not distinct from 'I drink'; -- tomo
update public.forms set gloss_en = 'I work; (noun) job, work' where id = '81c85f2f-1730-5868-8508-cda305d7e976' and gloss_en is not distinct from 'I work'; -- trabajo
update public.forms set gloss_en = 'helps (he/she helps); (noun) help' where id = '0d6492d2-b459-5120-a855-0dd8c1853703' and gloss_en is not distinct from 'helps (he/she helps)'; -- ayuda
update public.forms set gloss_en = 'asks (he/she asks); (noun) question' where id = '33b055a9-a073-5693-bd8b-6ddad2f4eb72' and gloss_en is not distinct from 'asks (he/she asks)'; -- pregunta
update public.lemmas set gloss_en = 'tasty, delicious; rich', gloss_note_en = 'For food it means tasty. For people it means rich (wealthy).' where id = 'accd7de4-099d-5790-950a-ab5e1e325a90' and gloss_en is not distinct from 'tasty, delicious' and gloss_note_en is not distinct from null; -- rico
update public.lemmas set gloss_note_en = 'Fish as food. A live fish in the water is pez.' where id = '36266bfa-ebff-56ba-a819-2ab9a7ae2cc7' and gloss_note_en is not distinct from 'fish as food'; -- pescado
update public.lemmas set gloss_en = 'to want; to love (a person)' where id = '9f36dba5-abc3-5065-83f0-32181c195852' and gloss_en is not distinct from 'to want'; -- querer
update public.lemmas set gloss_note_en = 'At a restaurant, la carta is the menu. A credit or ID card is tarjeta.' where id = '58cbab3e-4ea1-53b6-acf1-eab7c34c0030' and gloss_note_en is not distinct from null; -- carta
update public.lemmas set gloss_note_en = 'Salami, cheese, olives, peanuts, shared with drinks; often before an asado.' where id = '7f8a7080-7cb3-51bc-99f9-c2cfb04e90f1' and gloss_note_en is not distinct from 'shared before a meal'; -- picada
update public.lemmas set gloss_en = 'subject, course' where id = '5e328028-b443-5128-b36b-e96a0363a89c' and gloss_en is not distinct from 'school subject'; -- materia
update public.lemmas set gloss_en = 'police; police officer' where id = 'daebd94b-0da1-52b3-82f2-e8bc49aeee96' and gloss_en is not distinct from 'police'; -- policía
update public.lemmas set gloss_note_en = 'On its own, carne usually means beef in Argentina.' where id = '2cf8f88c-cfe5-58f5-808d-82cbfbe5af41' and gloss_note_en is not distinct from null; -- carne
update public.forms set gloss_en = 'brings (he/she brings)' where id = '7c9ae88a-67b4-59d3-b950-f3c390c23d8c' and gloss_en is not distinct from 'brings (people bring)'; -- trae
update public.lemmas set gloss_note_en = 'Often lives in the building; cleans, takes out the trash, fixes small things. Not the manager (la administración).' where id = 'cb6b88c8-8e0f-5fc3-b78d-1019670919f6' and gloss_note_en is not distinct from null; -- encargado
update public.lemmas set gloss_note_en = 'Apartments are counted in ambientes: all rooms except kitchen and bathroom. 2 ambientes = one-bedroom.' where id = 'a571e323-51a7-59aa-902e-741d97b0fcbe' and gloss_note_en is not distinct from 'how a flat''s size is counted'; -- ambiente
update public.lemmas set gloss_note_en = 'Means floor or story. For an apartment say depto, not piso as in Spain.' where id = 'f2692096-1842-5cec-a557-cf956c2c3f99' and gloss_note_en is not distinct from null; -- piso
update public.forms set gloss_en = 'we rent, we rented' where id = 'f589aa26-9fa2-5d75-8e38-441f0525937c' and gloss_en is not distinct from 'we rented'; -- alquilamos
update public.lemmas set gloss_en = 'half' where id = '297ee08d-4da3-55d0-8c22-159e94ed2151' and gloss_en is not distinct from 'half (past)'; -- media
update public.lemmas set gloss_note_en = 'On the 29th many Argentines eat ñoquis (gnocchi), with money under the plate for luck.' where id = 'e275c0e9-6f63-5e7f-b1aa-775310935f72' and gloss_note_en is not distinct from null; -- veintinueve
update public.lemmas set gloss_note_en = 'Also ''I put up with, I support'' (from bancar): no lo banco = I can''t stand him; te banco = I support you.' where id = 'c16b8fb3-0aae-53c3-9bd8-1746835659c4' and gloss_note_en is not distinct from null; -- banco
update public.lemmas set gloss_en = 'laundromat, laundry room' where id = 'bd95a4d6-3004-5eb2-81da-1352256a3966' and gloss_en is not distinct from 'laundromat'; -- lavadero
update public.lemmas set gloss_note_en = 'Not a library (that''s biblioteca). Many librerías mostly sell school and office supplies.' where id = 'd9f065f6-f0a0-598b-8bd4-cd13fbedf450' and gloss_note_en is not distinct from null; -- librería
update public.lemmas set gloss_note_en = 'People go to the boliche very late, usually after 1 or 2 a.m.' where id = '5e449b33-c537-537c-9c28-c101fabe0e96' and gloss_note_en is not distinct from null; -- boliche
update public.forms set gloss_en = 'a lot, a lot of' where id = '96dafc25-1e82-547f-bd3d-37b79fd426ed' and gloss_en is not distinct from 'a lot of'; -- mucho
update public.lemmas set gloss_note_en = 'Also used for prices (¿Cuánto sale? = How much is it?) and dating (salir con alguien).' where id = 'b9446739-a0bd-574f-9dab-10075b457108' and gloss_note_en is not distinct from null; -- salir
update public.lemmas set gloss_en = 'swimming pool; sink', gloss_note_en = 'In Argentina pileta is a swimming pool, and also the kitchen or bathroom sink.' where id = '1a82b464-b833-5b6f-b7be-aef2288cdcd4' and gloss_en is not distinct from 'swimming pool' and gloss_note_en is not distinct from null; -- pileta
