update public.forms set gloss_en = 'he/she will be able to' where id = '3d6ca628-b4cf-58ab-a921-0960e252b377' and gloss_en is not distinct from 'will be able to, can probably'; -- podrá
update public.forms set gloss_en = '(that) I/he/she goes out, leaves; (that) it goes well' where id = 'e40fb290-c0cc-5675-a9f8-e71d0b393c18' and gloss_en is not distinct from 'turns out, goes (that it go)'; -- salga
update public.forms set gloss_en = 'I thought, I believed' where id = 'e2cfaefe-ecc5-5a82-9454-467cc9cb1901' and gloss_en is not distinct from 'I believed'; -- creí
update public.forms set gloss_en = 'parties; the holidays' where id = '38facbbd-f5b4-5433-9631-2262d85453d5' and gloss_en is not distinct from 'parties'; -- fiestas
update public.lemmas set gloss_note_en = 'volver a + verb = to do again: volvió a llover = it rained again.' where id = '1c74d674-430e-539b-b6b7-39c28bf4326a' and gloss_note_en is not distinct from null; -- volver
update public.lemmas set gloss_en = 'to go around, to be (lately); to work (machines); to ride', gloss_note_en = 'No anda = it doesn''t work. ¿Cómo andás? = how are you? Andar en bici = to ride a bike.' where id = '61811c56-de80-5854-b4d6-5a54254e1ed6' and gloss_en is not distinct from 'to go, to walk' and gloss_note_en is not distinct from null; -- andar
update public.lemmas set gloss_en = 'to listen, to hear', gloss_note_en = 'In Argentina escuchar is the normal word for ''hear'' too: no te escucho = I can''t hear you.' where id = '26012c0b-feb3-5194-aef0-83e4f75a3885' and gloss_en is not distinct from 'to listen' and gloss_note_en is not distinct from null; -- escuchar
