update public.lemmas set gloss_en = 'to pass, to happen, to come in, to come by', gloss_note_en = 'Also ''to send, to give'': pasame tu número = give me your number.' where id = 'ddef54fa-fb1c-5679-afd1-d9db9c14272b' and gloss_en is not distinct from 'to pass, to come in' and gloss_note_en is not distinct from null; -- pasar
update public.forms set gloss_en = 'he came back, she came back' where id = '2c1278fc-bb8c-5534-9a9e-750cc0b1f889' and gloss_en is not distinct from 'he came back, he did again'; -- volvió
