update public.forms set gloss_en = 'works (it works); he/she is, has been' where id = '87d1fadf-25bc-5f17-bf18-af28374d3bb3' and gloss_en is not distinct from 'works (it works)'; -- anda
update public.forms set gloss_en = 'you''re, you''ve been (lately)' where id = 'bc568482-ca3b-5d5f-a6ef-bbcde6f99acf' and gloss_en is not distinct from 'you''re going around (doing)'; -- andás
update public.forms set gloss_en = 'was working (it); was (lately); rode, used to ride' where id = 'df829ab2-2992-5232-91c0-bcbf7eca39a0' and gloss_en is not distinct from 'rode, used to ride, went around'; -- andaba
update public.forms set gloss_en = 'I wait, I hope' where id = 'baa93584-42f4-520e-97d6-8eacb6b3cf1e' and gloss_en is not distinct from 'I wait'; -- espero
