update public.forms set gloss_en = 'will happen; I wonder (what''s happening)', gloss_note_en = 'Future often shows a guess: ¿Qué le pasará? = I wonder what''s wrong with him.' where id = '5ea4806b-8b36-588f-b652-75e756219366' and gloss_en is not distinct from 'will happen, is probably wrong' and gloss_note_en is not distinct from null; -- pasará
update public.lemmas set gloss_en = 'street number, height', gloss_note_en = 'In addresses, altura is the street number. ¿A qué altura? = whereabouts on the street? A esta altura = at this point.' where id = 'b16d5bea-7a06-5199-ba6e-cdc551e020a4' and gloss_en is not distinct from 'block number (of a street)' and gloss_note_en is not distinct from '¿a qué altura? — which block?'; -- altura
update public.lemmas set gloss_en = 'to keep going, to continue, to follow' where id = 'd779f819-1cb3-581f-a5e1-646578a7a8eb' and gloss_en is not distinct from 'to keep on, to still be'; -- seguir
update public.lemmas set gloss_en = 'to get on, to get in' where id = 'f56277cf-eb3c-51c9-87b2-a633f1a8897d' and gloss_en is not distinct from 'to get on'; -- subirse
update public.lemmas set gloss_en = 'hundred (in 101–199); percent (por ciento)' where id = '82d8b542-3916-5d2c-9a5c-3c2c846c1a98' and gloss_en is not distinct from 'hundred (in 101–199)'; -- ciento
update public.forms set gloss_en = 'you leave, you let' where id = '6f29322f-6a82-5367-92ef-c5d4fcfc8654' and gloss_en is not distinct from 'you leave (something) (don''t leave it)'; -- dejes
update public.forms set gloss_en = 'left, quit' where id = '1447110b-7ffa-5862-a0dd-598f4bea012e' and gloss_en is not distinct from 'quit, given up'; -- dejado
