update public.forms set gloss_en = 'you left, you quit' where id = 'b33fb42a-1e52-53f8-972a-2ea8210b0a35' and gloss_en is not distinct from 'you stopped, you quit'; -- dejaste
update public.forms set gloss_en = 'they left, they stopped' where id = '16cd53be-23c1-59e7-9461-4d9e03fd596e' and gloss_en is not distinct from 'they stopped, they quit'; -- dejaron
update public.forms set gloss_en = 'you keep, you continue' where id = 'fb003b05-20a5-58df-8d13-86fb39ecb729' and gloss_en is not distinct from 'you keep (that you keep: well)'; -- sigas
update public.lemmas set gloss_en = 'to cost, to be hard' where id = 'd17af3b8-68ec-5210-81e1-906adc72cd9a' and gloss_en is not distinct from 'to cost'; -- costar
update public.lemmas set gloss_note_en = '''No tengo un mango'' = I''m broke. ''Al mango'' = at maximum (volume, speed, AC).' where id = '451553ac-e017-5e0b-ad02-55bd3d88394a' and gloss_note_en is not distinct from null; -- mango
update public.lemmas set gloss_note_en = 'The everyday word for money in Argentina; ''dinero'' sounds formal.' where id = 'b0789da3-46a6-5bf3-8a68-1bb25c21149d' and gloss_note_en is not distinct from null; -- plata
update public.lemmas set gloss_note_en = 'Coins or small bills you have. The change you get back after paying is ''el vuelto''.' where id = '7216906e-6004-5564-a610-83182e693f12' and gloss_note_en is not distinct from null; -- cambio
update public.lemmas set gloss_note_en = 'In Argentina ''bañarse'' usually means taking a shower, not a bath.' where id = '0b4ad584-b976-5a08-838e-f4514703496d' and gloss_note_en is not distinct from null; -- bañarse
update public.forms set gloss_en = '(that) I get paid, (that) he/she charges' where id = '6c6d1eb8-ae4f-52f0-98fc-baaa94402846' and gloss_en is not distinct from 'get paid (when I, when he/she get paid)'; -- cobre
update public.forms set gloss_en = 'we had dinner, we have dinner' where id = '9c729598-6e79-5588-b3f8-4f8d2910e5c4' and gloss_en is not distinct from 'we had dinner'; -- cenamos
update public.forms set gloss_en = 'he/she has dinner; dinner' where id = 'ed3e6930-d00f-522b-94e4-d6f136818cc8' and gloss_en is not distinct from 'has dinner (people have dinner)'; -- cena
update public.lemmas set gloss_en = 'to let (someone) know, to tell, to warn' where id = 'd32f8623-eb52-5fa3-8337-8c86316dac22' and gloss_en is not distinct from 'to let know'; -- avisar
update public.lemmas set gloss_en = 'field, court, stadium', gloss_note_en = '''Ir a la cancha'' = go to a soccer game. Also any sports court. ''Tener cancha'' = to have experience.' where id = 'b9077f29-ea15-5a23-aa14-7102df0233dc' and gloss_en is not distinct from 'field, stadium' and gloss_note_en is not distinct from null; -- cancha
update public.lemmas set gloss_note_en = 'False friend: means great, not ''barbaric''. ''Me cae bárbaro'' = I really like him.' where id = 'b0560671-fc29-5afb-b1b9-04906ab90841' and gloss_note_en is not distinct from null; -- bárbaro
update public.lemmas set gloss_en = 'to prepare, to make (food)' where id = 'd0e935e1-90ff-57f9-8b8b-1c4c4880b1f2' and gloss_en is not distinct from 'to prepare, to get ready'; -- preparar
update public.lemmas set gloss_en = 'barbecue, Argentine grill', gloss_note_en = 'Slow wood/coal grill of beef, sausages and offal; a long social meal, often Sunday. Also a rib cut.' where id = '70a14779-eb6e-55da-a2e7-6a4686aaf849' and gloss_en is not distinct from 'barbecue' and gloss_note_en is not distinct from null; -- asado
update public.lemmas set gloss_en = 'idiot, dude', gloss_note_en = 'Between friends it means ''dude''; said in anger it means ''idiot''. Rude to strangers.' where id = 'ada1b01b-d818-56a0-b9b7-d36e11aae35a' and gloss_en is not distinct from 'dude' and gloss_note_en is not distinct from 'between friends only — rude to a stranger'; -- boludo
update public.lemmas set gloss_en = 'to invite, to treat (pay for someone)', gloss_note_en = '''Te invito'' / ''invito yo'' usually means I''m paying for you.' where id = '4df4e48b-0e9f-5b4f-9ead-cb28fd4a9da7' and gloss_en is not distinct from 'to invite' and gloss_note_en is not distinct from null; -- invitar
update public.forms set gloss_en = 'preparing, making' where id = '27d83813-20df-5619-b7a3-1751ec6636fe' and gloss_en is not distinct from 'preparing, getting ready'; -- preparando
update public.lemmas set gloss_en = 'to be (located), to be left, to agree on (a time or place)', gloss_note_en = 'Queda cerca = it''s close; ¿quedan? = are there any left?; quedamos a las 8 = we agreed on 8.' where id = '530e7934-b54e-56b6-800d-101f92882e10' and gloss_en is not distinct from 'to arrange, to agree' and gloss_note_en is not distinct from null; -- quedar
update public.lemmas set gloss_note_en = 'With a place it means visiting for the first time: conocer Córdoba = to see Córdoba (for the first time).' where id = '1a7b1576-a7cd-5994-99ec-f1ac9ecf87a9' and gloss_note_en is not distinct from null; -- conocer
update public.lemmas set gloss_note_en = 'Recién llegué = I just got here. Also ''not until'': recién el lunes = not until Monday.' where id = 'a1ee9206-3d42-54f3-81c0-77f10a39561d' and gloss_note_en is not distinct from null; -- recién
update public.lemmas set gloss_note_en = 'False friend: in Argentina a recital is any live music show (rock, pop), not a classical solo.' where id = 'a6b1debb-ac8f-54a1-9b88-26f7fd75d3bb' and gloss_note_en is not distinct from null; -- recital
update public.lemmas set gloss_en = 'to have a (good or bad) time', gloss_note_en = 'Always with la: la pasé bárbaro = I had a great time; ¿la pasaste bien? = did you have a good time?' where id = '20de66ee-8ff3-55dd-b3b0-fc2263a3c700' and gloss_en is not distinct from 'to have a time (good or bad)' and gloss_note_en is not distinct from null; -- pasarla
update public.lemmas set gloss_note_en = 'Very common but informal; avoid it in formal settings. Also used for a big problem or fuss.' where id = 'd963fc62-2907-5f21-9153-166f7f98dbbf' and gloss_note_en is not distinct from null; -- quilombo
update public.lemmas set gloss_note_en = 'Said alone, "¡Tranquilo!" or "¡Tranqui!" means "relax, don''t worry".' where id = 'fa2e805f-ba02-5ebc-9ac5-b516e71f3672' and gloss_note_en is not distinct from null; -- tranquilo
update public.lemmas set gloss_en = 'molar, back tooth' where id = '565e22a0-5b79-536f-bb51-350b7bd0a073' and gloss_en is not distinct from 'tooth (back tooth)'; -- muela
update public.lemmas set gloss_note_en = 'Also ''shift'' and ''your turn''. Sacar turno = book an appointment (doctor, bank, paperwork).' where id = '85908235-a56c-509c-ab83-65bf5c3fc37b' and gloss_note_en is not distinct from null; -- turno
update public.lemmas set gloss_en = 'allergy' where id = '5f536fd8-ac8f-599f-be17-5f25b83911c3' and gloss_en is not distinct from 'allergy, hay fever'; -- alergia
update public.lemmas set gloss_en = 'Band-Aid, small bandage' where id = 'd33a7cfa-ae54-5b2f-a379-6b1e079686d9' and gloss_en is not distinct from 'plaster, Band-Aid'; -- curita
update public.lemmas set gloss_note_en = '"¡Ojo!" alone means "careful!" or "watch out!".' where id = '01832479-ae09-5ed8-943f-f3ae830e2bb4' and gloss_note_en is not distinct from null; -- ojo
update public.lemmas set gloss_note_en = 'Me da miedo / vergüenza / fiaca = it scares me / I''m embarrassed / I can''t be bothered.' where id = '2bc0b8a1-cdf5-5489-9f5f-ab9612dc0078' and gloss_note_en is not distinct from null; -- dar
update public.lemmas set gloss_note_en = 'A long-distance or charter bus. A city bus is a colectivo (or bondi).' where id = '7a688d53-8966-5e83-a326-0e27de13bff9' and gloss_note_en is not distinct from null; -- micro
update public.lemmas set gloss_en = 'mountain, the mountains' where id = '2ea0edbc-1de9-5d48-8b6c-ed6e7c01e49c' and gloss_en is not distinct from 'mountains'; -- montaña
update public.lemmas set gloss_note_en = 'A travel ticket (bus, plane). For a show or game it''s an entrada.' where id = 'ff60e03a-522f-5054-b09b-0d42b5dd8386' and gloss_note_en is not distinct from null; -- pasaje
update public.lemmas set gloss_note_en = 'At Argentine beach clubs (balnearios), a carpa is a shade tent you rent by the day or season.' where id = 'ef763b5b-9171-59ad-9cd6-a911952781e6' and gloss_note_en is not distinct from null; -- carpa
update public.lemmas set gloss_note_en = '''La Costa'' often means the beach towns of Buenos Aires province, like Mar del Plata or Pinamar.' where id = '2a16ed90-cbe0-5832-94c2-069443488584' and gloss_note_en is not distinct from null; -- costa
update public.lemmas set gloss_note_en = '''Las sierras'' usually means the hills of Córdoba, a classic holiday spot.' where id = '308eaf55-3fd5-5c8b-9257-bc7118781e69' and gloss_note_en is not distinct from null; -- sierra
update public.lemmas set gloss_en = 'to tell; to count' where id = '3625e546-790b-56f2-bef8-b322153f4bba' and gloss_en is not distinct from 'to tell'; -- contar
update public.lemmas set gloss_en = 'story; history' where id = 'bfa7654b-63a7-5777-b268-48837c23c040' and gloss_en is not distinct from 'story'; -- historia
update public.lemmas set gloss_en = 'annoying situation, a drag' where id = 'f0cd9f3b-5862-5102-b6f1-fdd5d083297d' and gloss_en is not distinct from 'drag, bummer'; -- garrón
update public.lemmas set gloss_en = 'anyway; the same' where id = 'f552e0a2-82e5-508b-a79e-5bc7b038b19a' and gloss_en is not distinct from 'anyway'; -- igual
update public.lemmas set gloss_note_en = 'The white smock kids wear over their clothes in Argentine public schools.' where id = '80bc11ba-b792-5dea-91d9-6d0d8a59962f' and gloss_note_en is not distinct from null; -- guardapolvo
update public.lemmas set gloss_note_en = 'In Argentina a hamaca is a swing; a hammock is a hamaca paraguaya.' where id = '7d2b6a00-68bb-52d5-a6fc-ee4383db468a' and gloss_note_en is not distinct from null; -- hamaca
update public.lemmas set gloss_note_en = 'Bife de chorizo is a sirloin steak, not sausage.' where id = 'd26d4f36-a3de-5329-9cab-7f0c278df843' and gloss_note_en is not distinct from null; -- bife
update public.lemmas set gloss_note_en = 'In restaurants people usually leave about 10%, often in cash.' where id = '9c9aafa9-88ad-50ee-a817-6ac382fcd684' and gloss_note_en is not distinct from null; -- propina
update public.lemmas set gloss_note_en = 'Grilled provolone with oregano, a classic starter at an asado or parrilla.' where id = '3196a76b-a870-5c1f-beaa-493bb5e50a21' and gloss_note_en is not distinct from null; -- provoleta
update public.lemmas set gloss_note_en = 'Casual: ''tipo seis'' = around six. Also used as a filler, like English ''like''.' where id = 'cad7e491-b928-5ea4-8c37-47ae4d7bb870' and gloss_note_en is not distinct from null; -- tipo
update public.lemmas set gloss_note_en = 'Often means the WhatsApp group. Slang: ''es (todo) grupo'' = it''s a lie.' where id = '290cb964-9b46-56c0-8f84-a7de4e8dc1fb' and gloss_note_en is not distinct from null; -- grupo
update public.lemmas set gloss_en = 'Christmas fruit bread, panettone', gloss_note_en = 'Sweet bread with dried fruit eaten at Christmas and New Year''s in Argentina.' where id = 'c0c32ec4-4d1e-5d39-973e-d4f695effcc5' and gloss_en is not distinct from 'panettone' and gloss_note_en is not distinct from null; -- pan dulce
update public.lemmas set gloss_note_en = 'On the 29th of each month Argentines eat ñoquis with money under the plate for luck.' where id = '55356ef5-daac-5da4-9e13-301dbf04354c' and gloss_note_en is not distinct from null; -- ñoquis
update public.lemmas set gloss_note_en = 'Literally ''little tree''. Slang: street money changers who buy and sell dollars.' where id = '0d6383ee-4b0d-5c2d-b69f-6baaf473d46b' and gloss_note_en is not distinct from null; -- arbolito
update public.lemmas set gloss_note_en = 'Cheap sparkling cider is the classic drink for the Christmas and New Year''s toast.' where id = '330a856e-38c7-54bc-987d-709e4fe2e087' and gloss_note_en is not distinct from null; -- sidra
update public.lemmas set gloss_en = 'to worry, to get worried' where id = '4777463c-0260-5d8d-b2ff-5fd478cd382f' and gloss_en is not distinct from 'to get worried'; -- preocuparse
update public.lemmas set gloss_en = 'red (in the face); redhead', gloss_note_en = '''Ponerse colorado'' = to blush. In Argentina ''colorado'' also means a redhead.' where id = 'f5c8dfa1-8d3c-5c8d-82b2-2c521481e829' and gloss_en is not distinct from 'red-faced' and gloss_note_en is not distinct from null; -- colorado
update public.lemmas set gloss_note_en = '''Seguro llueve'' often means ''it''ll probably rain, I bet'': less certain than ''definitely''.' where id = '2b3b2964-e8e7-577a-9a84-517e20bcbb8a' and gloss_note_en is not distinct from null; -- seguro
update public.lemmas set gloss_en = 'end of the year, New Year''s Eve' where id = '123c2d53-2921-5b72-848d-140eec1ff247' and gloss_en is not distinct from 'end of the year'; -- fin de año
update public.lemmas set gloss_en = 'move (house), moving' where id = 'ab65ce2c-8fe6-5646-8ae2-b663af4825d0' and gloss_en is not distinct from 'move, removal'; -- mudanza
update public.lemmas set gloss_note_en = 'Neighborhood carousel; kids try to grab the ''sortija'' (ring) to win a free ride.' where id = 'b489a293-b44e-5e8d-a595-744418121fd0' and gloss_note_en is not distinct from null; -- calesita
update public.lemmas set gloss_note_en = 'Kids collect and swap them to fill the album, especially the World Cup album.' where id = 'abc18fe3-7e31-50b0-9608-0e30cdb02c28' and gloss_note_en is not distinct from null; -- figurita
update public.lemmas set gloss_en = 'candy, sweet treat' where id = '7ba46502-40b0-5f35-a6a1-ca7e4f3d4991' and gloss_en is not distinct from 'sweet, treat'; -- golosina
update public.lemmas set gloss_en = 'to be enough; to hand, to pass' where id = 'c34c5437-382f-5f09-9b40-9a8152477fee' and gloss_en is not distinct from 'to hand, to reach'; -- alcanzar
update public.forms set gloss_en = 'make yourselves (comfortable), put on (you all)' where id = 'dea78b46-6357-5447-ab74-dc6130733038' and gloss_en is not distinct from 'make yourselves (comfortable)'; -- pónganse
update public.lemmas set gloss_en = 'to take, to carry; to have been (for a time)' where id = 'd92aed4c-0a6a-52e2-977c-ba653771aff7' and gloss_en is not distinct from 'to take, to carry'; -- llevar
update public.lemmas set gloss_en = 'to go up, to rise; to carry up, to get on' where id = '5f9f27e0-83cf-5d60-9531-c7222d5c21a6' and gloss_en is not distinct from 'to go up, to rise'; -- subir
update public.lemmas set gloss_en = 'paperwork, official procedure', gloss_note_en = 'Any official task at an office or bank (ID, permits, paying bills). Often slow and a big part of daily life.' where id = '428e5637-af53-508d-a211-5cb0b43a3cbc' and gloss_en is not distinct from 'paperwork, errand' and gloss_note_en is not distinct from null; -- trámite
update public.lemmas set gloss_en = 'to fill in, to fill out; to complete' where id = 'b38eb1b9-2704-5554-8ed8-d5ad333973ae' and gloss_en is not distinct from 'to fill in'; -- completar
update public.lemmas set gloss_en = 'it''s needed, (you) need' where id = 'bcb658ba-069e-502f-aee5-1de023f6334d' and gloss_en is not distinct from 'it''s needed, is needed'; -- hace falta
update public.lemmas set gloss_note_en = 'Also means a city block (the whole square). For distance Argentines say ''cuadra'': ''a dos cuadras''.' where id = '414d8c33-ead1-5696-bfe3-ef1ba802c8c9' and gloss_note_en is not distinct from null; -- manzana
update public.lemmas set gloss_note_en = 'Plain ''jamón'' usually means cooked ham; cured ham (like prosciutto) is ''jamón crudo''.' where id = 'b37ce1d0-44ed-5935-8303-1ce0991213fd' and gloss_note_en is not distinct from null; -- jamón
update public.lemmas set gloss_en = 'to charge, to load; to top up; to tease', gloss_note_en = 'Also ''to tease'': ''¿Me estás cargando?'' = Are you kidding me? Cargar la SUBE = top up your transit card.' where id = 'b318b760-9208-5f67-a6ca-3da2d4d26bce' and gloss_en is not distinct from 'to charge, to load' and gloss_note_en is not distinct from null; -- cargar
update public.lemmas set gloss_en = 'to cut out, to go out (power)' where id = '20b3d899-b552-5040-bb0c-dd73a3cdcf8e' and gloss_en is not distinct from 'to cut out'; -- cortarse
update public.lemmas set gloss_note_en = 'Also slang for a person: ''me colgué'' = I got distracted, I forgot.' where id = '6103172a-b7d8-5ff8-afa1-612796c43016' and gloss_note_en is not distinct from null; -- colgarse
update public.lemmas set gloss_en = 'data (on your phone); details, info' where id = '1396b926-71d8-5890-bd32-c1b2a3aff6bb' and gloss_en is not distinct from 'data (on your phone)'; -- datos
update public.lemmas set gloss_en = 'to put; to set (the table); to make (someone feel)' where id = '453aac22-007c-5a7e-a38a-7c678487f00d' and gloss_en is not distinct from 'to put'; -- poner
update public.forms set gloss_en = 'I take, I carry; I''ve been (for a time)' where id = 'ef2b5fe8-1c05-5f5f-bb87-77466fb59db5' and gloss_en is not distinct from 'I take'; -- llevo
update public.forms set gloss_en = 'it cut out, it went out' where id = '2fc76854-62b2-5413-a25a-82ccc8ce3334' and gloss_en is not distinct from 'it cut out'; -- se cortó
update public.forms set gloss_en = 'puts, sets; gets (+ feeling)' where id = '449ac41e-717b-5cb2-b38c-d183dbdb292a' and gloss_en is not distinct from 'puts, sets (people set)'; -- pone
update public.lemmas set gloss_note_en = 'False friend: in Argentina it means working from home, not a home office room.' where id = '70009e41-01c2-5015-b533-d78fef591a50' and gloss_note_en is not distinct from null; -- home office
update public.lemmas set gloss_note_en = 'Required by law, not a bonus for good work: half paid in June, half in December.' where id = 'd3736897-cce7-504a-8b3e-d9da9bb98b24' and gloss_note_en is not distinct from null; -- aguinaldo
update public.lemmas set gloss_note_en = 'For a doctor, bank or office appointment Argentines say turno, not cita.' where id = '17f72c10-e70a-5082-87ce-7470d62acec9' and gloss_note_en is not distinct from null; -- cita
update public.lemmas set gloss_en = 'to cut, to break up' where id = '4332df3a-5b7e-55bd-9de9-261ce6ada4a0' and gloss_en is not distinct from 'to break up'; -- cortar
update public.lemmas set gloss_note_en = '''Chau, un beso'' or ''besos'' is a normal goodbye with friends and family, on the phone or in texts.' where id = 'a677158a-d385-5a6f-88af-ecd7c5bd217f' and gloss_note_en is not distinct from null; -- beso
update public.lemmas set gloss_en = 'to meet, to know each other' where id = '4d292f8a-5ef6-547f-b130-ba8582756e56' and gloss_en is not distinct from 'to meet (each other)'; -- conocerse
update public.lemmas set gloss_note_en = 'As an adjective it means ''capable'', but in Argentine speech it often means ''maybe'': capaz (que) llueve.' where id = '6068a742-e7fb-50c5-979e-a218b03a5a11' and gloss_note_en is not distinct from null; -- capaz
update public.lemmas set gloss_en = 'maybe' where id = '40376b9a-012d-5811-b029-2761eef902ce' and gloss_en is not distinct from 'for all I know, it may be'; -- a lo mejor
update public.lemmas set gloss_note_en = 'For small mistakes Argentines usually say perdón; lo siento is for bad news or sympathy.' where id = '4475f347-4834-5eb2-850d-91ea443e302c' and gloss_note_en is not distinct from null; -- lo siento
update public.lemmas set gloss_note_en = 'Health insurance run by unions or the state, paid from your salary. Private plans are called prepaga.' where id = '11c993d5-fc06-5c4e-8960-ae934d6a87f7' and gloss_note_en is not distinct from null; -- obra social
update public.lemmas set gloss_en = 'prescription, recipe' where id = 'bdb1d33b-d652-5845-8b04-876ba09ee4f4' and gloss_en is not distinct from 'prescription'; -- receta
update public.lemmas set gloss_en = 'blood pressure, pressure' where id = '96a471d8-0843-5dc7-aff7-c3956f127992' and gloss_en is not distinct from 'blood pressure'; -- presión
