update public.lemmas set gloss_note_en = '''¡Genio!'' or ''¡Sos un genio!'' is a common casual way to say thanks.' where id = '584e23df-92cc-54f7-a98e-f22d3844b43c' and gloss_note_en is not distinct from null; -- genio
