update public.lemmas set gloss_note_en = 'Rock sung in Spanish from Argentina: Charly García, Soda Stereo, Los Redondos.' where id = '1e1306ce-d62f-5280-9549-f51a16d9feda' and gloss_note_en is not distinct from null; -- rock nacional
update public.lemmas set gloss_en = 'offal, grilled organ meat', gloss_note_en = 'At an asado: chinchulines, mollejas, riñones, often eaten first.' where id = '3147f4ba-0b1e-54c2-a049-742f4ec3a8ac' and gloss_en is not distinct from 'offal' and gloss_note_en is not distinct from null; -- achuras
update public.lemmas set gloss_note_en = 'Steak order: vuelta y vuelta (very rare), jugoso (rare), a punto (medium), cocido (well done).' where id = '917e90a6-d9a0-51c6-8651-d4dae7b633a6' and gloss_note_en is not distinct from null; -- jugoso
update public.lemmas set gloss_en = 'strip steak, sirloin steak', gloss_note_en = 'A beef cut, not a sausage. The classic Argentine steak.' where id = '7d2e86d8-7568-5670-9b3d-9ea71e099a04' and gloss_en is not distinct from 'sirloin steak' and gloss_note_en is not distinct from null; -- bife de chorizo
update public.lemmas set gloss_note_en = 'Per-person restaurant charge for bread and table service. ''Cubiertos'' also means knives and forks.' where id = 'c90422a7-12fe-5d4f-9f13-ca75778b004d' and gloss_note_en is not distinct from null; -- cubierto
update public.lemmas set gloss_en = 'commitment, plans', gloss_note_en = '''Tengo un compromiso'' = I have something on, often a polite excuse. Also means engagement to marry.' where id = 'e39f84c8-4069-5fba-9a5e-cd45859506a7' and gloss_en is not distinct from 'prior engagement, commitment' and gloss_note_en is not distinct from null; -- compromiso
update public.lemmas set gloss_en = 'to mess up, to say or do the wrong thing' where id = '7e83fed7-685f-548a-a333-54c2e1bb19eb' and gloss_en is not distinct from 'to put your foot in it'; -- meter la pata
update public.lemmas set gloss_en = 'to go back (in time), to undo' where id = '93d007f4-6077-5a53-9791-f4a884b9e7ce' and gloss_en is not distinct from 'to turn back the clock'; -- volver atrás
update public.lemmas set gloss_note_en = 'Argentines end messages with ''besos'' or ''besitos'' even to friends; it''s not romantic.' where id = '991b8bc8-f62d-5269-91a4-f1201e44541f' and gloss_note_en is not distinct from null; -- besito
update public.lemmas set gloss_en = 'nice and warm, nice and hot' where id = '8c955d52-c35c-541f-9dc7-e66aa51fd618' and gloss_en is not distinct from 'nice and warm, fresh from the oven'; -- calentito
update public.lemmas set gloss_en = 'chilly weather, a slight chill' where id = 'f8f9a413-68e4-5738-ac2a-f7c8b831349b' and gloss_en is not distinct from 'a nip in the air, chilly weather'; -- fresquito
update public.lemmas set gloss_en = 'just like, exactly like' where id = 'a6512cde-f582-5b27-9c17-1bdedcdb25dd' and gloss_en is not distinct from 'just like, the spitting image of'; -- igualito
update public.lemmas set gloss_en = 'quickly, real quick' where id = '0c0de3e3-8774-58ec-a330-b6c9da03c25a' and gloss_en is not distinct from 'real quick'; -- rapidito
update public.lemmas set gloss_en = 'the thing about; someone''s place', gloss_note_en = '''A lo de Sofi'' = to Sofi''s house. Very common in Argentina.' where id = '13c1fcab-997c-56f8-8806-6c03e114d667' and gloss_en is not distinct from 'the business with, the thing about' and gloss_note_en is not distinct from null; -- lo de
update public.lemmas set gloss_en = 'the thing is' where id = '84730068-c902-57cb-b553-dc1fa1ae5fc2' and gloss_en is not distinct from 'what''s going on is'; -- lo que pasa es que
update public.lemmas set gloss_en = 'whatever, anything' where id = 'bd906134-e51e-50c6-87b2-4e06293448e7' and gloss_en is not distinct from 'whatever it is, anything goes'; -- lo que sea
update public.lemmas set gloss_note_en = 'Literally: there''s no bad thing that doesn''t bring something good.' where id = '5b15630e-a052-5039-a6bc-94bcaccfb48d' and gloss_note_en is not distinct from null; -- no hay mal que por bien no venga
update public.lemmas set gloss_note_en = 'Don''t complain about something you got for free.' where id = 'b74e8240-0a7b-5ab2-b279-569b0d66bbc9' and gloss_note_en is not distinct from null; -- a caballo regalado no se le miran los dientes
update public.lemmas set gloss_en = 'if you don''t ask, you don''t get', gloss_note_en = 'Literally: the baby who doesn''t cry doesn''t get fed.' where id = '96a508de-f594-54e2-9bd9-c5bc43aecad4' and gloss_en is not distinct from 'the squeaky wheel gets the grease' and gloss_note_en is not distinct from null; -- el que no llora no mama
update public.lemmas set gloss_note_en = 'Literally: whoever gets burned by milk cries when they see a cow.' where id = '9ced80d6-cf6f-5f1f-b948-96651486541c' and gloss_note_en is not distinct from null; -- el que se quema con leche, ve una vaca y llora
update public.lemmas set gloss_note_en = 'Common among friends, but can sound disrespectful. Avoid in polite talk.' where id = '04c790c6-060c-5ed8-9934-0a40e67be78c' and gloss_note_en is not distinct from null; -- mina
update public.lemmas set gloss_en = 'over the top, wild; out of line' where id = 'fb88805e-d89f-5e9f-9c65-a98800b0def9' and gloss_en is not distinct from 'over the top, wild'; -- zarpado
update public.forms set gloss_en = 'fan chants' where id = 'b7e79f66-57a0-59b2-a964-b3fd3b704fd1' and gloss_en is not distinct from 'terrace chants'; -- cantitos
update public.forms set gloss_en = 'I messed up' where id = '3c9d9f63-7013-517c-a557-80e8adf045c9' and gloss_en is not distinct from 'I put my foot in it'; -- metí la pata
update public.lemmas set gloss_note_en = 'Very common but a bit crude (pedo = fart). Fine with friends, not at work.' where id = '157af036-ebde-5995-8735-73bf5383c933' and gloss_note_en is not distinct from null; -- al pedo
update public.lemmas set gloss_en = 'fake, uptight, snobby', gloss_note_en = 'Also someone who doesn''t party or do drugs. A ''boliche careta'' is a posh, uptight club.' where id = '41bce121-c9ee-59a1-9859-cbc2041afa58' and gloss_en is not distinct from 'straight-laced, phony' and gloss_note_en is not distinct from null; -- careta
update public.lemmas set gloss_en = 'very excited, hyped up' where id = '87768c48-4d9e-560e-bf24-06a7e5cef540' and gloss_en is not distinct from 'hyped up, wound up'; -- manija
update public.lemmas set gloss_note_en = 'Crude but very common; ''en pedo'' means drunk, so literally ''not even drunk''. ''Ni ahí'' is softer.' where id = '8e6200b6-27d0-5d08-b0f0-982609373659' and gloss_note_en is not distinct from null; -- ni en pedo
update public.lemmas set gloss_note_en = 'Argentines say ''me hace acordar a…'' (with ''a'') for ''reminds me of''.' where id = 'b2938925-b5eb-5693-adc7-8cf4915ed131' and gloss_note_en is not distinct from null; -- hacer acordar
update public.lemmas set gloss_en = 'to go a long way, to pay off (time, money)', gloss_note_en = 'In Argentina ''rendir un examen'' also means to take an exam.' where id = 'efd150c8-afed-5cd0-9dca-c2c154561d99' and gloss_en is not distinct from 'to go further, to be worth it (time, money)' and gloss_note_en is not distinct from null; -- rendir
update public.lemmas set gloss_note_en = '''El ajuste'' is also the word for government spending cuts, a hot political topic.' where id = 'b4121493-ccc3-59f3-94e3-2d437c7b26be' and gloss_note_en is not distinct from null; -- ajuste
update public.lemmas set gloss_en = 'registered, on the books (a job)', gloss_note_en = 'A job ''en blanco'' is registered: taxes, pension, health insurance and paid holidays.' where id = '208ec1cb-11fa-5248-8d7c-15feab83fda9' and gloss_en is not distinct from 'on the books (a job)' and gloss_note_en is not distinct from null; -- en blanco
update public.lemmas set gloss_en = 'unregistered, off the books (a job)', gloss_note_en = 'Very common in Argentina: paid cash, no contract, no benefits.' where id = '2b58f20f-55ef-574a-b771-346ddbf97bac' and gloss_en is not distinct from 'off the books (a job)' and gloss_note_en is not distinct from null; -- en negro
update public.lemmas set gloss_en = 'it makes me uneasy, I feel awkward about it' where id = 'a450a00b-a61c-5811-ab57-9125337ffb8a' and gloss_en is not distinct from 'it makes me uneasy'; -- me da cosa
update public.lemmas set gloss_en = 'it upsets me, it gets me down' where id = '468ab1bf-9098-528c-8e0b-d33ec9fca800' and gloss_en is not distinct from 'it gets me down'; -- me pone mal
update public.lemmas set gloss_en = 'distress, deep sadness', gloss_note_en = 'In Argentina ''angustia'' is closer to heavy sadness or being upset than to anxiety (''ansiedad'').' where id = '4757d01e-3c12-5cae-856f-dd51af7e4ffb' and gloss_en is not distinct from 'distress, anxiety' and gloss_note_en is not distinct from null; -- angustia
update public.lemmas set gloss_note_en = '''Las Cataratas'' usually means Iguazú Falls, in Misiones.' where id = '4da376d4-0cf7-5bdb-adac-c9814e8df0ab' and gloss_note_en is not distinct from null; -- cataratas
update public.lemmas set gloss_note_en = 'Not a light bulb (that''s ''lamparita''). It has a filter at the bottom; don''t stir with it.' where id = 'daf9a600-67bc-59e7-97ee-4cbaee04252e' and gloss_note_en is not distinct from null; -- bombilla
update public.lemmas set gloss_note_en = 'One person (the cebador) refills and hands the mate to each person in turn; you give it back to them.' where id = '82c284da-dd28-5d9c-8a30-15927ce060e8' and gloss_note_en is not distinct from null; -- cebar
update public.lemmas set gloss_en = 'yerba mate (the dried leaves)' where id = '367e7a20-4e7e-5e4a-b04a-8a1127aea492' and gloss_en is not distinct from 'mate leaves'; -- yerba
update public.lemmas set gloss_note_en = 'Usually ''bizcochitos de grasa'': small flaky savory crackers eaten with mate.' where id = 'ffb24d6c-851e-52c0-bdf3-468038a3e786' and gloss_note_en is not distinct from null; -- bizcochito
update public.lemmas set gloss_note_en = 'Careful: ''calentarse'' can mean to get angry or to get turned on.' where id = 'a2e9e8b2-6bd2-5c8b-a658-70a2a39707d8' and gloss_note_en is not distinct from null; -- calentar
update public.lemmas set gloss_note_en = 'Mate is ''lavado'' when the yerba has lost its flavor after many refills; time to change it.' where id = 'f15ad8f0-986e-5425-b704-a0e7e2ccb5f1' and gloss_note_en is not distinct from null; -- lavado
update public.lemmas set gloss_note_en = 'Around 5 pm, often mate or coffee with facturas. Argentines eat dinner late.' where id = '76f502a6-521c-53cb-b92b-923bb2fa161b' and gloss_note_en is not distinct from null; -- merienda
update public.lemmas set gloss_note_en = 'Classic with mate, especially on rainy days.' where id = 'aee179c8-744c-5a18-b971-c88350d8ffa7' and gloss_note_en is not distinct from null; -- torta frita
update public.lemmas set gloss_note_en = 'Crowded shared house where poor immigrants rented rooms around 1900, e.g. in La Boca and San Telmo.' where id = '17cb36a6-58f1-5530-996b-57498f84ebc6' and gloss_note_en is not distinct from null; -- conventillo
update public.lemmas set gloss_en = 'Spanish, from Spain', gloss_note_en = 'Argentines call any Spaniard ''gallego'', not only people from Galicia.' where id = 'd9bd6c1f-c2cf-54ad-9f09-cc3662b2c75c' and gloss_en is not distinct from 'Spanish (in Argentina: any Spaniard)' and gloss_note_en is not distinct from null; -- gallego
update public.lemmas set gloss_en = 'joke, prank', gloss_note_en = 'Chiste = a joke you tell; broma = a prank, or something said not seriously.' where id = 'e77b79f9-7a4e-5909-bd28-d2fd92bafadc' and gloss_en is not distinct from 'prank, practical joke' and gloss_note_en is not distinct from null; -- broma
update public.lemmas set gloss_note_en = 'Vivo = sly, street-smart. Hacerse el vivo = trying to take advantage of others.' where id = 'c9dada88-1450-547c-bece-adf3aea4cf74' and gloss_note_en is not distinct from null; -- hacerse el vivo
update public.lemmas set gloss_note_en = 'Argentines say casamiento much more than boda.' where id = '0a380803-8e5c-5c46-9b1e-0d093935a74c' and gloss_note_en is not distinct from null; -- casamiento
update public.lemmas set gloss_en = 'godfather; wedding sponsor', gloss_note_en = 'At Argentine weddings the padrino is usually the bride''s father, who walks her in; not a ''best man''.' where id = 'a58f161c-0dcd-5489-b7f9-d0ab42b029ca' and gloss_en is not distinct from 'godfather; best man' and gloss_note_en is not distinct from null; -- padrino
update public.lemmas set gloss_note_en = 'The legal wedding is always at the Registro Civil; a church wedding and party are extra.' where id = '069f93e7-9627-5052-9eef-52eb4e8ac238' and gloss_note_en is not distinct from null; -- por civil
update public.lemmas set gloss_en = 'espresso with a little milk', gloss_note_en = 'Standard café order. A ''lágrima'' is the opposite: mostly milk with a drop of coffee.' where id = '13f8597b-c4b4-5f48-86b5-ec84a6733f5b' and gloss_en is not distinct from 'cortado' and gloss_note_en is not distinct from 'espresso with a little milk'; -- cortado
update public.forms set gloss_en = 'godmother; wedding sponsor', gloss_note_en = 'At Argentine weddings the madrina is usually the groom''s mother, who walks him in; not a ''maid of honor''.' where id = '514ef728-f5cb-5362-b9e5-73754ebca556' and gloss_en is not distinct from 'godmother; maid of honor' and gloss_note_en is not distinct from null; -- madrina
